-- Users are global (a person can belong to many workspaces), so NO workspace_id here.
-- This is the one deliberate exception to the tenant-key rule. ASSUMED.
CREATE TABLE users (
  id               uuid PRIMARY KEY,
  email            text NOT NULL,                      -- PROVEN: user.email unique
  username         text NOT NULL,                      -- PROVEN
  display_name     text,
  initials         text,                               -- PROVEN
  color            text,                               -- PROVEN
  avatar_url       text,                               -- PROVEN profile_picture
  timezone         text,                               -- PROVEN user_preference.timezone
  locale           text,                               -- ASSUMED
  email_verified_at timestamptz,                       -- PROVEN as bool email_validated; timestamp is ASSUMED
  default_workspace_id uuid,                           -- PROVEN; FK added in section Z
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')), -- ASSUMED
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  version          integer NOT NULL DEFAULT 1
);

-- Login lookup, case-insensitive. Partial so a deleted user frees the address (ASSUMED).
CREATE UNIQUE INDEX users_email_uk ON users (lower(email)) WHERE deleted_at IS NULL;

-- cross-service FK removed: ALTER TABLE users ADD CONSTRAINT users_default_workspace_fk FOREIGN KEY (default_workspace_id) REFERENCES workspaces(id)

-- 'manual','repeated_failure','scope_deleted'
ALTER TABLE users ADD COLUMN anonymized_at timestamptz;

-- =============================================================================
-- 10. IDENTITY and SECURITY  (SEC-003..006, SEC-009, SEC-012, FR-1006, FR-1008, L-11, L-12)
-- =============================================================================
CREATE TABLE user_credentials (                             -- global like users, no workspace_id
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  password_hash text,                                       -- argon2id, NULL for SSO-only users
  password_changed_at timestamptz,
  breached_checked_at timestamptz,
  failed_attempts smallint NOT NULL DEFAULT 0, locked_until timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE user_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device_label text, ip inet, user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(),
  idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);

CREATE INDEX user_sessions_user ON user_sessions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE data_subject_requests (
  id uuid PRIMARY KEY,
  workspace_id uuid /* id -> access.workspaces */,
  user_id uuid NOT NULL REFERENCES users(id),
  kind text NOT NULL CHECK (kind IN ('export','delete')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','blocked_by_hold','done','rejected')),
  due_at timestamptz NOT NULL,                              -- NFR-012: 30 days
  created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz
);

-- ===== NEW for the split (plan/tech/02-data-and-cells.md)

-- "My workspaces" and sign-in routing without asking every cell. Copy kept from access member.* events.
CREATE TABLE user_workspaces (
  user_id         uuid NOT NULL REFERENCES users(id),
  workspace_id    uuid NOT NULL,                     -- id -> access.workspaces (in some cell)
  cell_id         text NOT NULL,                     -- id -> routing.cells
  workspace_name  text NOT NULL,
  role_kind       text NOT NULL CHECK (role_kind IN ('owner','admin','member','guest')),
  status          text NOT NULL CHECK (status IN ('active','pending','deactivated')),
  source_version  integer NOT NULL,                  -- member row version; older events are ignored
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, workspace_id)
);

-- One-time tokens: email verification, password reset. Hashed, single use, short life.
CREATE TABLE auth_tokens (
  token_hash      bytea PRIMARY KEY,
  user_id         uuid NOT NULL REFERENCES users(id),
  kind            text NOT NULL CHECK (kind IN ('verify_email','reset_password')),
  expires_at      timestamptz NOT NULL,
  used_at         timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX auth_tokens_user_idx ON auth_tokens (user_id, kind);

-- Token signing keys. Private key material stays in the cloud key service (KMS); only a reference here.
-- Published as JWKS; rotate every 90 days, keep the old key until all its tokens expired.
CREATE TABLE signing_keys (
  kid             text PRIMARY KEY,
  algorithm       text NOT NULL DEFAULT 'EdDSA',
  public_jwk      jsonb NOT NULL,
  kms_key_ref     text NOT NULL,
  status          text NOT NULL CHECK (status IN ('next','active','retiring','retired')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  retire_after    timestamptz
);
CREATE UNIQUE INDEX signing_keys_one_active_uk ON signing_keys (status) WHERE status = 'active';

-- Global service: rows are per user, not per workspace; the service filters by the signed-in user.
COMMENT ON TABLE user_workspaces IS 'rls:exempt global, filtered by user';
COMMENT ON TABLE idempotency_keys IS 'rls:exempt global service';
